package local.pitv;
import android.app.*;import android.view.*;import android.widget.*;import android.graphics.*;import org.json.*;import java.util.*;

/** Provider movies and series browse inside the existing guide's list area. */
final class GuideCatalogPanel extends ListView {
 final CableGuideScreen guide;final IptvActivity app;String kind="vod",level="categories",caption="",query="";JSONArray data=new JSONArray();final ArrayList<Integer> visible=new ArrayList<>();final ArrayDeque<State> history=new ArrayDeque<>();int serial;boolean loading,interrupted;Runnable retry;
 static final class State {final String level,title,query;final JSONArray data;final int row,first,top;State(GuideCatalogPanel p){level=p.level;title=p.caption;query=p.query;data=p.data;row=p.getSelectedItemPosition();first=p.getFirstVisiblePosition();top=p.getChildCount()==0?0:p.getChildAt(0).getTop();}}
 final BaseAdapter rows=new BaseAdapter(){public int getCount(){return loading?1:Math.max(1,visible.size());}public Object getItem(int pos){return loading||visible.isEmpty()?null:data.optJSONObject(visible.get(pos));}public long getItemId(int pos){return pos;}public View getView(int pos,View old,android.view.ViewGroup parent){TextView row=old instanceof TextView?(TextView)old:guide.text("",14);JSONObject item=(JSONObject)getItem(pos);String name=loading?"Loading "+caption+"…":item==null?(retry==null?"No titles in this list":"Could not load · OK to retry"):name(item);String detail=item==null?"":item.optString("year",item.optString("releaseDate",item.optString("releasedate","")));row.setText(name+(detail.isEmpty()?"":"\n"+detail));row.setTextColor(TvStyle.INK);row.setMaxLines(2);row.setGravity(Gravity.CENTER_VERTICAL);row.setPadding(guide.dp(12),guide.dp(6),guide.dp(12),guide.dp(6));row.setMinHeight(guide.dp(43));return row;}};
 GuideCatalogPanel(CableGuideScreen host){super(host.app);guide=host;app=host.app;setBackgroundColor(0xff101518);setDivider(new android.graphics.drawable.ColorDrawable(0xff293139));setDividerHeight(guide.dp(1));setSelector(guide.shape(0xff294559,TvStyle.CYAN));setAdapter(rows);setOnItemSelectedListener(new OnItemSelectedListener(){public void onItemSelected(AdapterView<?> p,View v,int n,long id){describe();}public void onNothingSelected(AdapterView<?> p){}});setOnItemClickListener((p,v,n,id)->activate(n));setOnKeyListener((v,key,e)->{if(e.getAction()!=KeyEvent.ACTION_DOWN)return false;if(key==KeyEvent.KEYCODE_DPAD_LEFT){guide.focusSection();return true;}if(key==KeyEvent.KEYCODE_DPAD_UP&&getSelectedItemPosition()<=0){guide.nowTool.requestFocus();return true;}if(key==KeyEvent.KEYCODE_DPAD_RIGHT)return true;return false;});}
 void cancel(){serial++;interrupted|=loading;loading=false;retry=null;}
 void open(String type){if(interrupted||!kind.equals(type)||data.length()==0){kind=type;history.clear();categories();}else{requestFocus();describe();}}
 void categories(){history.clear();query="";request("categories",app.title(kind),()->app.demo?new JSONArray("[{\"category_id\":\"1\",\"category_name\":\"English demo collection\"}]"):new JSONArray(app.cachedApi("get_"+kind+"_categories","")),false);}
 interface Fetch {JSONArray get()throws Exception;}
 void request(String destination,String title,Fetch fetch,boolean push){if(push)history.push(new State(this));int ticket=++serial;interrupted=false;level=destination;caption=title;query="";loading=true;retry=null;guide.groupName.setText(title+" · Loading…");guide.programme.setText(title);guide.schedule.setText("");guide.description.setText("Browse without leaving Television");guide.next.setText("");rows.notifyDataSetChanged();requestFocus();app.worker.submit(()->{try{JSONArray result=fetch.get();app.runOnUiThread(()->{if(ticket!=serial||!guide.catalogActive||app.isFinishing())return;loading=false;data=result;filter();setSelection(0);describe();});}catch(Exception ignored){app.runOnUiThread(()->{if(ticket!=serial||!guide.catalogActive)return;loading=false;data=new JSONArray();retry=()->request(destination,title,fetch,false);filter();guide.description.setText("Provider unavailable. Select OK to retry, or Back to return.");});}});}
 String name(JSONObject item){return item.optString("name",item.optString("title",item.optString("category_name","Untitled")));}
 boolean englishSeriesOnly(){return (kind.equals("series")||kind.equals("vod"))&&app.getSharedPreferences(kind.equals("vod")?"movie-language":"series-language",0).getBoolean("categoryEnglishOnly",true);}
 boolean seriesVisible(JSONObject item){return !englishSeriesOnly()||!level.equals("categories")||SeriesLanguage.categoryVisible(name(item));}
 void filter(){visible.clear();for(int n=0;n<data.length();n++){JSONObject item=data.optJSONObject(n);if(item!=null&&seriesVisible(item)&&name(item).toLowerCase(Locale.ROOT).contains(query.toLowerCase(Locale.ROOT)))visible.add(n);}rows.notifyDataSetChanged();guide.groupName.setText(caption+(englishSeriesOnly()&&level.equals("categories")?" · English & streaming services":"")+" · "+visible.size()+(level.equals("categories")?" categories":level.equals("seasons")?" seasons":level.equals("episodes")?" episodes":" titles"));}
 JSONObject selected(){int pos=getSelectedItemPosition();return pos>=0&&pos<visible.size()?data.optJSONObject(visible.get(pos)):null;}
 void describe(){JSONObject item=selected();if(item==null||loading)return;guide.programme.setText(name(item));guide.schedule.setText(level.equals("categories")?"Choose a category":level.equals("seasons")?"Choose a season":level.equals("episodes")?"Select to watch episode":kind.equals("vod")?"Movie · Select for details and playback":"Series · Select for seasons and episodes");guide.description.setText(item.optString("plot",item.optString("description","")));guide.next.setText(item.optString("genre",""));if(!app.hasLivePlayback()){guide.technical.setText("");String url=item.optString("cover",item.optString("stream_icon",""));guide.preview.state.setText("Select to browse / watch");guide.preview.setImageBitmap(guide.image(url,()->{JSONObject current=selected();if(current!=null&&url.equals(current.optString("cover",current.optString("stream_icon",""))))guide.preview.setImageBitmap(app.images.get(url));}));}}
 void activate(int pos){if(loading)return;if(retry!=null){retry.run();return;}if(pos<0||pos>=visible.size())return;JSONObject item=data.optJSONObject(visible.get(pos));if(item==null)return;
  if(level.equals("categories")){String category=item.optString("category_id");request("titles",name(item),()->app.demo?app.sampleItems(kind):new JSONArray(app.cachedApi(kind.equals("series")?"get_series":"get_vod_streams",category.isEmpty()?"":"&category_id="+app.enc(category))),true);}
  else if(level.equals("titles")&&kind.equals("series")){String id=item.optString("series_id");request("seasons",name(item),()->{JSONObject info=app.demo?new JSONObject("{\"episodes\":{\"1\":[{\"id\":\"1\",\"title\":\"Episode 1\",\"container_extension\":\"mp4\"}]}} "):new JSONObject(app.fetch(app.api("get_series_info","&series_id="+app.enc(id))));JSONObject episodes=info.optJSONObject("episodes");if(episodes==null)throw new java.io.IOException();ArrayList<String> keys=new ArrayList<>();Iterator<String> it=episodes.keys();while(it.hasNext())keys.add(it.next());Collections.sort(keys,(a,b)->{try{return Integer.compare(Integer.parseInt(a),Integer.parseInt(b));}catch(Exception ignored){return a.compareTo(b);}});JSONArray out=new JSONArray();for(String season:keys)out.put(new JSONObject().put("name","Season "+season).put("episodes",episodes.optJSONArray(season)));return out;},true);}
  else if(level.equals("seasons")){history.push(new State(this));level="episodes";caption=name(item);data=item.optJSONArray("episodes");if(data==null)data=new JSONArray();query="";filter();setSelection(0);describe();}
  else if(level.equals("episodes")){if(app.demo){app.message("Connect your provider to watch.");return;}try{String url=app.stream("series",item.optString("id"),item.optString("container_extension","mp4"));app.playCatalog(guide,name(item),url,data,visible.get(pos));}catch(Exception ignored){app.message("This episode could not be opened.");}}
  else movie(item);
 }
 void movie(JSONObject item){if(app.demo){app.message("Connect your provider to watch.");return;}String title=name(item);app.load(()->{JSONObject info;try{JSONObject result=new JSONObject(app.cachedApi("get_vod_info","&vod_id="+app.enc(item.optString("stream_id"))));info=result.optJSONObject("info");}catch(Exception ignored){info=null;}if(info==null)info=item;String plot=info.optString("plot",info.optString("description","Watch this movie?"));String metadata=info.optString("genre","")+"  "+info.optString("releaseDate",info.optString("releasedate",""))+"  "+info.optString("duration","");String message=metadata.trim().isEmpty()?plot:metadata.trim()+"\n\n"+plot;return ()->new AlertDialog.Builder(app).setTitle(title).setMessage(message).setPositiveButton("Watch",(d,w)->{try{app.playCatalog(guide,title,app.stream("movie",item.optString("stream_id"),item.optString("container_extension","mp4")),null,-1);}catch(Exception ignored){app.message("This movie could not be opened.");}}).setNegativeButton("Cancel",null).show();});}

 void back(){cancel();if(history.isEmpty()){guide.showTv();return;}State state=history.pop();interrupted=false;level=state.level;caption=state.title;query=state.query;data=state.data;filter();setSelectionFromTop(Math.max(0,state.first),state.top);if(state.row>=0)setSelection(state.row);requestFocus();describe();}
 void search(){EditText input=new EditText(app);input.setSingleLine();input.setText(query);input.setHint("Search this list");new AlertDialog.Builder(app).setTitle("Find in "+caption).setView(input).setPositiveButton("Find",(d,w)->{query=input.getText().toString().trim();filter();setSelection(0);requestFocus();describe();}).setNegativeButton("Cancel",null).show();}
 void options(){ArrayList<String> choices=new ArrayList<>(Arrays.asList("Categories","Search this list","Back to live guide"));if(kind.equals("series")||kind.equals("vod"))choices.add(englishSeriesOnly()?"Groups: English & streaming services · Show all":"Groups: All · English & streaming services only");new AlertDialog.Builder(app).setTitle(app.title(kind)).setItems(choices.toArray(new String[0]),(d,n)->{if(n==0)categories();else if(n==1)search();else if(n==2)guide.showTv();else{app.getSharedPreferences(kind.equals("vod")?"movie-language":"series-language",0).edit().putBoolean("categoryEnglishOnly",!englishSeriesOnly()).apply();categories();}}).show();}
}
